            this.stk2.push(this.stk1.pop()!);
        }
        return this.stk1.at(-1)!;
    }

    forward(steps: number): string {
        for (let i = 0; i < steps && this.stk2.length; ++i) {
            this.stk1.push(this.stk2.pop()!);
        }
        return this.stk1.at(-1)!;
    }
}

